// Hand-written (NOT autogenerated). Guards the decoding that tools/ulsdkbuild
// emits: a false vector length or truncated bytes must return an error, and
// must not cause a large allocation.

package query

import (
	"encoding/binary"
	"runtime"
	"testing"

	flatbuffers "github.com/google/flatbuffers/go"
	"github.com/urbanlogiq/ulsdk/types/generated"
	"github.com/urbanlogiq/ulsdk/types/id"
)

// falseLength is the length written over a real vector length.
const falseLength = 0x40000000

// maxAlloc is the most that one decode may allocate.
const maxAlloc = 16 << 20

// setVectorLen writes n over the length of the vector that starts at
// element offset start.
func setVectorLen(data []byte, start uint32, n uint32) {
	binary.LittleEndian.PutUint32(data[start-4:], n)
}

// decodeAlloc runs decode and returns its error and the bytes that it
// allocated. FromBytes must return an error, not panic.
func decodeAlloc(decode func() error) (error, uint64) {
	var before, after runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&before)
	err := decode()
	runtime.ReadMemStats(&after)
	return err, after.TotalAlloc - before.TotalAlloc
}

func TestFalseTableVectorLength(t *testing.T) {
	data := (&TableSource{
		T:      &Placeholder{Idx: 0},
		Fields: []Expr{{Exprs: &Column{Name: "name"}}},
	}).ToBytes()
	fbs := generated.GetSizePrefixedRootAsTableSource(data, 0)
	tab := fbs.Table()
	start := uint32(tab.Vector(flatbuffers.UOffsetT(tab.Offset(8))))
	setVectorLen(data, start, falseLength)

	err, n := decodeAlloc(func() error { _, err := TableSourceFromBytes(data); return err })
	if err == nil {
		t.Fatal("decode returned no error for a false vector length")
	}
	if n > maxAlloc {
		t.Fatalf("decode allocated %d bytes, want at most %d", n, maxAlloc)
	}
}

func TestFalseByteVectorLength(t *testing.T) {
	data := (&DataCatalog{Id: id.ObjectId{B: streamID}}).ToBytes()
	dc := generated.GetSizePrefixedRootAsDataCatalog(data, 0)
	oid := dc.Id(nil)
	tab := oid.Table()
	start := uint32(tab.Vector(flatbuffers.UOffsetT(tab.Offset(4))))
	setVectorLen(data, start, falseLength)

	err, n := decodeAlloc(func() error { _, err := DataCatalogFromBytes(data); return err })
	if err == nil {
		t.Fatal("decode returned no error for a false vector length")
	}
	if n > maxAlloc {
		t.Fatalf("decode allocated %d bytes, want at most %d", n, maxAlloc)
	}
}

func TestTruncatedBytesReturnError(t *testing.T) {
	data := selectQuery().ToBytes()
	for _, n := range []int{0, 3, len(data) / 2} {
		if _, err := QueryFromBytes(data[:n]); err == nil {
			t.Fatalf("decode of %d of %d bytes returned no error", n, len(data))
		}
	}
}
